<template>
	<view class="container">
		<u-loading-page
		:loading="true" 
		v-if="load"
		fontSize="28rpx" />
		<block v-else>
		<view class="top-border"></view>
		<view class="inner">
			<view class="form">
				<block v-if="form.type==2">
					<view class="form-row">
						<text class="row-left">拥有积分</text>
						<view class="row-input">{{jifen}}</view>
					</view>
					<view class="form-row">
						<text class="row-left">我的金豆</text>
						<view class="row-input">{{jindou}}</view>
					</view>
				</block>
				<block v-else>
					<view class="form-row">
						<text class="row-left">拥有金豆</text>
						<view class="row-input">{{jindou}}</view>
					</view>
					<view class="form-row">
						<text class="row-left">我的余额</text>
						<view class="row-input">{{balance}}</view>
					</view>
				</block>
				<view class="form-row">
					<text class="row-left">{{form.type==2?'转化积分':'转化金豆'}}</text>
					<view class="row-input">
						<u-input
						    :placeholder="form.type==2?'请输入转化积分':'请输入转化金豆'"
							border="none"
							type="number"
							placeholderClass="placeholder28"
							v-model="form.money"
						    clearable />
					</view>
				</view>
				<view class="form-row">
					<text class="row-left">交易密码</text>
					<view class="row-input">
						<u-input
						    placeholder="请输入交易密码"
							border="none"
							password
							placeholderClass="placeholder28"
							v-model="form.paypwd"
						    clearable />
					</view>
				</view>
			</view>
			<view class="submit">
				<button type="default" class="submit-btn" @click="submit"
					:disabled="submitDisabled || isClose">{{isClose?'转化暂未开放':'转化'}}</button>
			</view>
			<view class="hint-container">
				<view class="hint-title">
					<image src="@/static/common/tishi.png" mode="widthFix" class="hint-img"/>
					<text>温馨提示</text>
				</view>
				<view class="hint-rows">
					<view class="hint-row" v-if="form.type==2">1积分等于{{change_config.jf_jd_bl}}金豆。</view>
					<view class="hint-row" v-else>转化收取{{change_config.jd_change_sxf}}手续费。</view>
				</view>
			</view>
		</view>
		<!-- #ifdef MP-WEIXIN -->
		<view class="mingxi" @click="toNext(`/pages/my/change-list`)">转化记录</view>
		<!-- #endif -->
		</block>
	</view>
</template>

<script>
	var validate = require("@/components/validate/validate.js");
	var _this;
	export default {
		data() {
			return {
				form:{
					step:1,
					money:'',
					paypwd:'',
					type:2,
				},
				submitDisabled:false,
				balance:0,
				jifen:0,
				jindou:0,
				change_config:{},
			}
		},
		onLoad(e) {
			_this = this;
			if (e.type) {
				_this.form.type = Number(e.type)
			}
			_this.tijiao()
		},
		onNavigationBarButtonTap(e) {
			_this.toNext(`/pages/my/change-list`);
		},
		computed:{
			isClose:{
				cache:false,
				get() {
					if (this.form.type==2) {
						return this.change_config.change_open == 0
					}
					return this.change_config.jd_change_open == 0
				}
			}
		},
		methods: {
			submit(){
				_this.form.step = 2
				_this.tijiao()
			},
			//提交
			async tijiao(){
				if (_this.form.step == 2) {
					var rule = [
						{
							name: 'money',
							rules: ['require', 'number'],
							errorMsg: {
								require: '请输入转化积分',
								number: '转化积分只能为数字'
							}
						},
						{
							name: 'paypwd',
							rules: ['require', 'min:6'],
							errorMsg: {
								require: '请输入交易密码',
								min: '交易密码最少6位'
							}
						}
						];
					// 是否全部通过，返回Boolean
					let checked = validate.check(this.form, rule);
					if (!checked) {
						// 获取错误信息
						let err = validate.getError();
						uni.$u.toast(err[0])
						return;
					}
					_this.submitDisabled = true
					setTimeout(()=>{
						_this.submitDisabled = false
					},2000)
				}
				const data = await _this.$post('port/user_change',_this.form)
				if (data.code==200) {
					uni.$u.toast(data.msg,()=>{
						_this.toNext(`/pages/my/change-list`,true)
					})
				}else if(data.code == -50){
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}else if(data.code == 50){
					uni.$u.toast(data.msg,()=>{
						_this.toNext(`/pages/my/paypwd?from=1`,true)
					})
				}else if(data.code == -1){
					_this.mobile = data.result.mobile
					_this.balance = data.result.balance
					_this.jifen = data.result.jifen
					_this.jindou = data.result.jindou
					_this.change_config = data.result.change_config
					if (_this.load) {
						_this.load = false
					}
				}else{
					uni.$u.toast(data.msg)
				}
			}
		}
	}
</script>
<style lang="scss" scoped>
	@import "static/css/form.scss";
	.container {
		height: 100%;
		position: relative;
		.inner{
			padding: 0 20rpx;
			.form{
				padding: 0 20rpx;
				.form-row{
					padding: 0;
				}
			}
		}
		.mingxi{
			position: fixed;
			top: 50%;
			right: 0;
			transform: translateY(-50%);
			background: rgba(#000, 0.6);
			min-width: 160rpx;
			color: #fff;
			height: 52rpx;
			line-height: 52rpx;
			text-align: center;
			border-radius: 30rpx 0 0 30rpx;
		}
	}
</style>